<!--
 * 国际化语言管理页面 — 展示语言条目列表，支持新增/编辑/删除
 *
 * @path apps\userinfo-web\src\views\system\language\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 国际化（列表页）
 * <p>语言（{@code ydsz_language}）的列表页，消费后端契约 LanguageController
 * （src/api/language.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询语言条目，支持新增/编辑/删除，搜索表单（语言名称/编码/状态）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/language';
import type { LanguageVO } from '#/api/models';

import LanguageForm from './language-form.vue';

defineOptions({ name: 'LanguageManagement' });

/** 判断语言状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

/** 判断是否为默认语言（契约 isDefault 为数字，1 默认 / 0 非默认） */
function isDefaultLanguage(isDefault?: number): boolean {
  return isDefault === 1;
}

const gridOptions: VxeTableGridOptions<LanguageVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'languageCode', title: '语言编码', width: 140 },
    { field: 'languageName', title: '语言名称', width: 160 },
    {
      field: 'isDefault',
      title: '默认语言',
      width: 100,
      slots: {
        default: ({ row }) => {
          const def = isDefaultLanguage(row.isDefault);
          return h(
            ElTag,
            { type: def ? 'success' : 'info', size: 'small' },
            () => (def ? '默认' : '非默认'),
          );
        },
      },
    },
    { field: 'sortOrder', title: '排序', width: 80, align: 'center' },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            ElTag,
            { type: enable ? 'success' : 'danger', size: 'small' },
            () => (enable ? '启用' : '禁用'),
          );
        },
      },
    },
    {
      field: 'action',
      title: '操作',
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => '编辑',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: '语言名称' },
        fieldName: 'languageName',
        label: '语言名称',
      },
      {
        component: 'Input',
        componentProps: { placeholder: '语言编码' },
        fieldName: 'languageCode',
        label: '语言编码',
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: '状态',
          options: [
            { label: '启用', value: '1' },
            { label: '禁用', value: '0' },
          ],
        },
        fieldName: 'status',
        label: '状态',
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: '搜索' },
    resetButtonOptions: { content: '重置' },
  },
});

// ========== 表单弹窗 ==========
const [LanguageFormModal, languageFormApi] = useYDSZModal({ connectedComponent: LanguageForm });

function handleAdd() {
  languageFormApi.open();
}

function handleEdit(row: LanguageVO) {
  languageFormApi.setData({ record: row });
  languageFormApi.open();
}

// ========== 删除 ==========
async function handleDelete(row: LanguageVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(
      `确定删除语言「${row.languageName ?? ''}」吗？`,
      '删除确认',
      { type: 'warning' },
    );
    await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="语言管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增语言</ElButton>
      </template>
    </Grid>
    <LanguageFormModal @success="gridApi.query()" />
  </Page>
</template>